window.kbPageData["views/entry/k-62150212afb07701"] = {"key":"entry/k-62150212afb07701","state":{"route":"entry/k-62150212afb07701"},"node":{"id":"k-62150212afb07701","mode":"k","title":"深入实施中华优秀传统文化传承发展工程","type":"观点与论证","domain":"文化","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["culture"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["文化"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"3.深入实施中华优秀传统文化传承发展工程\n主要内容：\n（1）核心思想理念。中华民族和中国人民在修齐治平、尊时守位、知常达变、开物成\n务、建功立业过程中培育和形成的基本思想理念，如革故鼎新、与时俱进的思想，脚踏实地、\n实事求是的思想，惠民利民、安民富民的思想，道法自然、天人合一的思想等，可以为人们\n认…","sources":[{"id":"4c71a679cd44373a","label":"深入实施中华优秀传统文化传承发展工程","topic":"发展与治理","category":"非时政","text":"3.深入实施中华优秀传统文化传承发展工程\n主要内容：\n（1）核心思想理念。中华民族和中国人民在修齐治平、尊时守位、知常达变、开物成\n务、建功立业过程中培育和形成的基本思想理念，如革故鼎新、与时俱进的思想，脚踏实地、\n实事求是的思想，惠民利民、安民富民的思想，道法自然、天人合一的思想等，可以为人们\n认识和改造世界提供有益启迪，可以为治国理政提供有益借鉴。传承发展中华优秀传统文化，\n就要大力弘扬讲仁爱、重民本、守诚信、崇正义、尚和合、求大同等核心思想理念。\n（2）中华传统美德。中华优秀传统文化蕴含着丰富的道德理念和规范，如天下兴亡、\n匹夫有责的担当意识，精忠报国、振兴中华的爱国情怀，崇德向善、见贤思齐的社会风尚，\n孝悌忠信、礼义廉耻的荣辱观念，体现着评判是非曲直的价值标准，潜移默化地影响着中国\n人的行为方式。传承发展中华优秀传统文化，就要大力弘扬自强不息、敬业乐群、扶危济困、\n见义勇为、孝老爱亲等中华传统美德。\n（3）中华人文精神。中华优秀传统文化积淀着多样、珍贵的精神财富，如求同存异、\n和而不同的处世方法，文以载道、以文化人的教化思想，形神兼备、情景交融的美学追求，\n俭约自守、中和泰和的生活理念等，是中国人民思想观念、风俗习惯、生活方式、情感样式\n的集中表达，滋养了独特丰富的文学艺术、科学技术、人文学术，至今仍然具有深刻影响。\n传承发展中华优秀传统文化，就要大力弘扬有利于促进社会和谐、鼓励人们向上向善的思想\n文化内容。\n——《关于实施中华优秀传统文化传承发展工程的意见》","source":{"doc":"6cbfb01fe723bba64b75","first":44,"last":45,"page":44,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"culture","title":"文化传承与创新表达"}],"units":{"k-62150212afb07701":[]}};
